sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float zoom;
uniform float offset;
uniform float mirror;
uniform float vertical;
uniform float angle;
uniform float sizing;

half4 main(float2 coord) {
    float3 h = toLayer * float3(coord, 1.0);
    if (abs(h.z) < 0.000001) return half4(0.0);
    float2 uv = (h.xy / h.z) / max(layer, float2(1.0));
    if (vertical > 0.5) uv.y += step(1.0, mod(uv.x, 2.0)) * offset;
    else uv.x += step(1.0, mod(uv.y, 2.0)) * offset;
    if (mirror > 0.5) uv = abs(mod(uv - float2(1.0), float2(2.0)) - float2(1.0));
    else uv = mod(uv, float2(1.0));
    float a = radians(angle);
    float c = cos(a);
    float s = sin(a);
    float2 p = uv - float2(0.5);
    float2 px = 1.0 / max(layer, float2(1.0));
    p /= max(float2(zoom, zoom) + px * 4.0, float2(0.0001));
    p.x *= layer.x / max(layer.y, 1.0);
    p = float2(c * p.x + s * p.y, -s * p.x + c * p.y);
    p.x *= layer.y / max(layer.x, 1.0);
    p += float2(0.5);
    float3 g = fromLayer * float3(p * layer, 1.0);
    return image.eval(g.xy / g.z);
}
